import fs from 'node:fs';
import path from 'node:path';
import { spawnSync } from 'node:child_process';
const root = process.cwd();
const {buildManifest} = await import(path.join(root, 'supervisor/green-manifest.mjs'));
const previous = JSON.parse(fs.readFileSync('supervisor/green-contracts.json', 'utf8'));
const result = spawnSync('git', ['ls-files', '--stage', '-z'], {encoding:'utf8'});
if (result.status) throw Error(result.stderr);
const files = new Map(result.stdout.split('\0').filter(Boolean).map(row => {
  const m=/^(\d{6}) \w+ \d\t(.+)$/.exec(row);if(!m)throw Error(row);return [m[2],{mode:m[1]}];
}));
const brain = {repo:'/Users/rewt/development/rewt/herdr-brain',identity:'/Users/rewt/development/rewt/herdr-brain/.git',org:'/Users/rewt/development/rewt/.org'};
const externalInputs = [
 '/Users/rewt/.gitconfig',
 '/Users/rewt/.gitconfig-rewt',
 '/Users/rewt/.gitconfig-bastian',
 '/Users/rewt/.config/git/config',
 '/opt/homebrew/etc/gitconfig',
 '/etc/gitconfig',
 '/Users/rewt/development/bastian/bch-cloak/.git/config',
 '/Users/rewt/development/bastian/bch-cloak/.herdr-release.json',
 '/Users/rewt/development/bastian/.lane.json',
 '/Users/rewt/development/rewt/herdr-brain/.git/config',
 '/Users/rewt/development/rewt/herdr-brain/.git/config.worktree',
 '/Users/rewt/development/rewt/.lane.json',
 '/Users/rewt/development/.lane.json',
 '/Users/rewt/.lane.json',
 '/Users/rewt/development/rewt/herdr-brain/.housekeeping.json',
 '/Users/rewt/development/rewt/.housekeeping.json',
 '/Users/rewt/development/rewt/herdr-brain/.herdr-release.json',
 '/Users/rewt/development/rewt/.org/config.json',
 '/Users/rewt/.herdr-monitor/fleet.json',
 '/Users/rewt/.local/share/herdr-monitor/current/contrib/settle-watch.mjs',
];
const manifest = buildManifest({files,bytes:file=>fs.readFileSync(file),read:file=>fs.readFileSync(file,'utf8')},{bindings:{brain,lab:null},externalInputs});
const exclusions = previous.exclusions;
const authority = exclusions.find(rule => rule.code === 'GREEN_SELF_AUTHORITY');
if (!authority.paths.includes('supervisor/GREEN-CONTRACTS.md')) authority.paths.push('supervisor/GREEN-CONTRACTS.md');
fs.writeFileSync('supervisor/green-contracts.json',JSON.stringify({...manifest,exclusions},null,2)+'\n');
console.log(JSON.stringify({boundary:Object.keys(manifest.boundary).length,components:manifest.components.map(c=>c.path),lab:manifest.bindings.lab}));
